     "summary": "当前存量PPP项目问题难以化解的最重要原因之一是地方政府财政紧张，无法按时向项目公司支付款项。同时，部分地方政府存在“新官不理旧账”的现象，新任官员暂停原有项目、要求解除合同、不履约、拖延付费。此外，部分项目超概算，也导致项目无法完成结算。",
